update sys_function_tl
FUNCTION_NAME = #{functionName}, FUNCTION_DESCRIPTION = #{functionDescription}, LAST_UPDATE_BY = #{lastUpdateBy}, LAST_UPDATE_DATE = #{lastUpdateDate}, LAST_UPDATE_LOGIN = #{lastUpdateLogin}
