update sys_function_b
PARENT_ID = #{parentId}, FUNCTION_CODE = #{functionCode}, FUNCTION_TYPE = #{functionType}, PATH = #{path}, PARAMETERS = #{parameters}, COMPONENT = #{component}, NAME = #{name}, REDIRECT = #{redirect}, HIDE_CHILDREN_IN_MENU = #{hideChildrenInMenu}, HIDE_IN_MENU = #{hideInMenu}, LOCK_IN_TAB = #{lockInTab}, MERGE_TAB = #{mergeTab}, OPEN_METHOD = #{openMethod}, KEEP_ALIVE = #{keepAlive}, ICON = #{icon}, VS_ID = #{vsId}, LAST_UPDATE_BY = #{lastUpdateBy}, LAST_UPDATE_DATE = #{lastUpdateDate}, LAST_UPDATE_LOGIN = #{lastUpdateLogin}
where function_id = #{functionId}

